2724	  async function createCompanyInviteForCompany(input: {
2725	    req: Request;
2726	    companyId: string;
2727	    allowedJoinTypes: "human" | "agent" | "both";
2728	    humanRole?: "owner" | "admin" | "operator" | "viewer" | null;
2729	    defaultsPayload?: Record<string, unknown> | null;
2730	    agentMessage?: string | null;
2731	  }) {
2732	    const normalizedAgentMessage =
2733	      typeof input.agentMessage === "string"
2734	        ? input.agentMessage.trim() || null
2735	        : null;
2736	    const effectiveHumanRole =
2737	      input.allowedJoinTypes === "agent"
2738	        ? null
2739	        : input.humanRole ?? "operator";
2740	    const insertValues = {
2741	      companyId: input.companyId,
2742	      inviteType: "company_join" as const,
2743	      allowedJoinTypes: input.allowedJoinTypes,
2744	      defaultsPayload: mergeInviteDefaults(
2745	        input.defaultsPayload ?? null,
2746	        normalizedAgentMessage,
2747	        effectiveHumanRole,
2748	      ),
2749	      expiresAt: companyInviteExpiresAt(),
2750	      invitedByUserId: input.req.actor.userId ?? null
2751	    };
2752	
2753	    let token: string | null = null;
2754	    let created: typeof invites.$inferSelect | null = null;
2755	    for (let attempt = 0; attempt < INVITE_TOKEN_MAX_RETRIES; attempt += 1) {
2756	      const candidateToken = createInviteToken();
2757	      try {
2758	        const row = await db
2759	          .insert(invites)
2760	          .values({
2761	            ...insertValues,
2762	            tokenHash: hashToken(candidateToken)
2763	          })
2764	          .returning()
2765	          .then((rows) => rows[0]);
2766	        token = candidateToken;
2767	        created = row;
2768	        break;
2769	      } catch (error) {
2770	        if (!isInviteTokenHashCollisionError(error)) {
2771	          throw error;
2772	        }
2773	      }
2774	    }
2775	    if (!token || !created) {
2776	      throw conflict("Failed to generate a unique invite token. Please retry.");
2777	    }
2778	
2779	    return { token, created, normalizedAgentMessage };
2780	  }
